// Bundles supabase/migrations/*.sql (in order) into supabase_full_setup.sql,
// a single re-runnable script for the Supabase SQL Editor.
// Usage: npm run db:bundle
import fs from "node:fs"
import path from "node:path"

const dir = "supabase/migrations"
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort()
const rule = "-- " + "=".repeat(75)

let out = `-- LuyChlat: full database setup (all migrations in order).
-- Generated by \`npm run db:bundle\` from supabase/migrations/ - edit those files, not this one.
--
-- Paste into Supabase › SQL Editor and click Run. Safe to re-run: existing
-- types, tables, columns, indexes and constraints are kept, functions,
-- triggers and policies are replaced with the latest version, and backfills
-- only touch rows that haven't been filled yet. It runs as one transaction,
-- so an error leaves the database unchanged.
`
for (const f of files) {
  const sql = fs.readFileSync(path.join(dir, f), "utf8").replace(/\r\n/g, "\n").trim()
  out += `\n\n${rule}\n-- ${f}\n${rule}\n\n${sql}\n`
}
fs.writeFileSync("supabase_full_setup.sql", out)
console.log(`supabase_full_setup.sql: ${files.length} migrations, ${out.split("\n").length} lines`)
